import { Component, createSignal, onCleanup, onMount } from "solid-js";

import LensManager, { LensActivationEvent, LensActivationEventName, LensName } from "#core/ui/lenses/lens-manager.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface MiniMapRadioButtonProps {
	caption: string;
	lens: LensName;
}

const MiniMapRadioButtonComponent: Component<MiniMapRadioButtonProps> = (props) => {
	const [activeLens, setActiveLens] = createSignal(LensManager.getActiveLens());

	onMount(() => {
		window.addEventListener(LensActivationEventName, onActiveLensChanged);
	});

	onCleanup(() => {
		window.removeEventListener(LensActivationEventName, onActiveLensChanged);
	});

	function onActiveLensChanged(event: LensActivationEvent) {
		setActiveLens(event.detail.activeLens);
	}

	return (
		<>
			<RadioButton
				class={"mr-2"}
				isChecked={activeLens() === props.lens}
				data-audio-group-ref={"minimap-radio-button"}
				onActivate={() => {
					LensManager.setActiveLens(props.lens);
				}}
			/>
			<L10n.Stylize
				class={"text-accent-2 text-base font-body pointer-events-auto"}
				text={props.caption}
			/>
		</>
	);
};

export const MiniMapRadioButton = ComponentRegistry.register({
	name: "MiniMapRadioButton",
	createInstance: MiniMapRadioButtonComponent,
});
